<template>
	<view>
		<view class="box_1 d-flex a-center j-center" @click="show=true">
			<image src="../static/icon14.png" mode=""></image>
			<span class="ml-16">新增分类</span>
		</view>
		<empty v-if="list.length==0"></empty>
		<view class="box_2 d-flex a-center j-sb" v-for="(item,index) in list " :key="index">
			<view class="box_2_title">
				{{item.name}}
			</view>

			<view class="d-flex a-center">
				<u-icon name='edit-pen' size="24" @click="glshow=true,category_id=item.id"></u-icon>
				<image class="mr-10 del-img ml-30" src="../static/cicon12.png" mode="widthFix"
					@click="delCategoryApi(item.id)">
			</view>

		</view>

		<u-popup :show="show" @close="show=false" :round="10" :closeable='true'>
			<view class="pop_box">
				<view class="txt-center f-size-30 f-600">
					新增分类
				</view>
				<view class="ipt_box">
					<input maxlength="10" type="text" v-model="name" placeholder="请输入分类名称" />
				</view>
				<view class="ipt_btn" @click="execCategoryApi()">
					保存
				</view>
			</view>
		</u-popup>

		<!-- 管理 -->
		<u-popup :show="glshow" @close="glshow=false" :round="10" :closeable='true'>
			<view class="pop_box">
				<view class="txt-center f-size-30 f-600">
					管理
				</view>
				<view class="ipt_box">
					<input maxlength="10" type="text" v-model="editname" placeholder="请输入" />
				</view>
				<view class="ipt_btn" @click="editexecCategoryApi">
					保存
				</view>
			</view>
		</u-popup>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				show: false,
				glshow: false,
				name: "",
				list: [],
				category_id: '',
				editname: '',
				page: 1

			};
		},
		onLoad() {
			this.categoryListApi()
		},
		onReachBottom() {
			this.page++
			this.categoryListApi(1)
		},
		methods: {
			async delCategoryApi(id) {
				let res = await this.delCategory({
					id
				})
				if (res.code == 1) {
					this.list.forEach((item, index) => {
						if (item.id == id) {
							this.list.splice(index, 1)
						}
					})
					this.$forceUpdate()
				}
			},
			// 修改分类
			async editexecCategoryApi() {
				console.log('this.editname', this.editname);
				let res = await this.execCategory({
					name: this.editname,
					category_id: this.category_id
				})
				if (res.code == 1) {
					this.glshow = false
					this.editname = ''
					this.categoryListApi()
				}
			},
			// 添加分类
			async execCategoryApi() {
				let res = await this.execCategory({
					name: this.name
				})
				if (res.code == 1) {
					this.show = false
					this.name = ''
					this.categoryListApi()
				}
			},
			async categoryListApi(e) {
				if (e !== 1) {
					this.page = 1
				}
				let res = await this.categoryList({
					page: this.page
				})
				if (res.code == 1) {
					if (e == 1) {
						this.list = [...this.list, ...res.data.rows]
					} else {
						this.list = res.data.rows
					}
				}
			}
		}
	}
</script>

<style lang="scss">
	page {
		padding: 30rpx 0;
		box-sizing: border-box;
		background: #F4F5F7;
	}

	.box_1 {
		width: 690rpx;
		height: 74rpx;
		background: #fff;
		border-radius: 10rpx;
		font-weight: 500;
		font-size: 32rpx;
		color: #3D3D3D;
		text-align: center;

		margin: 20rpx auto;
		padding: 16rpx 0;
		box-sizing: border-box;

		image {
			width: 36rpx;
			height: 36rpx;
		}
	}

	.box_2 {
		padding: 0 30rpx;
		box-sizing: border-box;
		background-color: #fff;
		margin-top: 30rpx;

		.del-img {
			width: 34rpx;
		}

		.box_2_title {
			font-weight: 600;
			font-size: 28rpx;
			color: #3D3D3D;
			margin: 22rpx 0;

		}

		.box_2_card {
			font-weight: 600;
			font-size: 24rpx;
			color: #036045;
		}

	}

	.ipt_box {
		width: 690rpx;
		height: 90rpx;
		background: #F8F9FC;
		border-radius: 16rpx 16rpx 16rpx 16rpx;
		padding: 22rpx 30rpx;
		box-sizing: border-box;
		margin: 60rpx 0 100rpx;
	}

	.pop_box {
		width: 750rpx;
		height: 544rpx;
		background: #FFFFFF;
		border-radius: 40rpx 40rpx 0rpx 0rpx;
		padding: 32rpx;
		box-sizing: border-box;

		.ipt_btn {
			width: 690rpx;
			height: 102rpx;
			background: #036045;
			border-radius: 1246rpx 1246rpx 1246rpx 1246rpx;
			text-align: center;
			line-height: 102rpx;
			font-size: 28rpx;
			color: #FFFFFF;
		}
	}
</style>